<?php
declare(strict_types=1);require_once __DIR__.'/../auth/seguridad.php';require_once __DIR__.'/../conexion_postgres.php';aplicarCors(['GET']);iniciarSesionSegura();$user=$_SESSION['user']['id']??null;$order=filter_var($_GET['order_id']??null,FILTER_VALIDATE_INT);if(!$user)responderJson(['resultado'=>'ERROR','mensaje'=>'No has iniciado sesión.'],401);if($order===false||$order<=0)responderJson(['resultado'=>'ERROR','mensaje'=>'Pedido no válido.'],400);
try{$q=retornarConexionPostgres()->prepare('select oi.id,oi.producto_id,p.nombre,oi.cantidad,oi.precio_unitario from public.order_items oi join public.orders o on o.id=oi.order_id join public.productos p on p.id=oi.producto_id where oi.order_id=:order_id and o.user_id=:user_id');$q->execute([':order_id'=>$order,':user_id'=>(int)$user]);responderJson(['resultado'=>'OK','items'=>$q->fetchAll()]);}catch(PDOException $e){error_log('Error líneas pedido: '.$e->getMessage());responderJson(['resultado'=>'ERROR','mensaje'=>'No se pudieron obtener las líneas del pedido.'],500);}
